import time
def timed(func):
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        print(func.__name__, round(time.perf_counter() - start, 4), "s")
        return result
    return wrapper
@timed
def total(n):
    return sum(range(n))
print(total(10**6))
